					atkHistInfo = atkHistQueue.GetAtIndex(num2);
					if (atkHistInfo != null && atkHistInfo.targetObjID == targetObjID && sameTargetTimeVal > Time.time - atkHistInfo.time)
						return false;
		else if (sameAttackTimeVal > 0f)
			for (int num3 = 14; num3 >= 0; num3--)
				atkHistInfo = atkHistQueue.GetAtIndex(num3);
				if (atkHistInfo != null && atkHistInfo.targetObjID == targetObjID && sameAttackTimeVal > Time.time - atkHistInfo.time && atkHistInfo.atkObjID == AttackerObjID)
